head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getCellDisabled]<br/>Row 인덱스와 Column 정보를 사용하여 특정 Cell 의 disabled 상태를 반환합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 disabled 상태를 조회할 Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "colInfo(필수) 파라미터로 disabled 상태를 조회할 Cell 의 Column 인덱스를 설정할 수 있어야 합니다. (숨겨진 Column 도 포함하여 인덱스가 설정됩니다.)",
        "setCellDisabled() 메소드로 disabled 상태를 true 로 설정한 Cell 은 true 를 반환해야 합니다.",
        "setCellDisabled() 메소드로 disabled 상태를 false 로 설정한 Cell 은 false 를 반환해야 합니다.",
        "setCellDisabled() 메소드로 disabled 상태를 설정하지 않은 Cell 은 ''(Empty String) 값을 반환해야 합니다.",
        "getCellDisabled() 메소드는 Cell 단위의 disabled 상태만 반환하며, Cell 의 최종 비활성화(disabled) 상태와는 다를 수 있습니다.",
        "반환값이 '' 인 Cell 은 상위 단위인 Row 또는 Column 의 disabled 상태가 적용되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="Cell(0,0)/(3,3) → setCellDisabled(true) 설정으로 true 반환 / Cell(1,2)/(2,2) → setCellDisabled(false) 설정으로 false 반환 / 그 외 Cell → 미설정으로 빈 문자열 반환 / Row 2 → setRowDisabled, Column 3 → setColumnDisabled (Cell 단위 미설정이라 빈 문자열 반환하나 실제 disabled 적용) / Column 1 → 숨김"', '', 'label1');

    // 조건 설정 (disabled/readonly Cell 을 배경색으로 구분: disabled=회색, readonly=연노랑)
    let properties = {
        dataList: "data:dlt_bind",
        disabledBackgroundColor: "#D3D3D3",
        readOnlyBackgroundColor: "#FFF8DC",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList);

    // 두번째 컬럼 숨김
    target1.setColumnVisible(1, false);

    // Cell(0,0)/(3,3) 에 disabled 설정
    target1.setCellDisabled(0, 0, true);
    target1.setCellDisabled(3, 3, true);
    // Cell(1,2)/(2,2) 에 disabled 해제
    target1.setCellDisabled(1, 2, false);
    target1.setCellDisabled(2, 2, false);

    // 상위 단위 disabled 설정 (Cell 단위는 미설정 → getCellDisabled 는 '' 반환하지만 실제 disabled 적용)
    target1.setRowDisabled(2, true);
    target1.setColumnDisabled(3, true);
}



scwin.btn_getCellDisabled_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let colInfo = Number(par_colInfo.getText());

    let rtn = target1.getCellDisabled(rowIndex, colInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getCellDisabled(" + rowIndex + ", " + colInfo + ") : " + rtn);
}
